CREATE INDEX idx_device_challenges_dev ON device_challenges (device_id);
CREATE INDEX idx_device_challenges_exp ON device_challenges (expires_at_ms);
CREATE INDEX idx_email_sends_tenant_ts ON email_sends(tenant_id, sent_at_ms);
CREATE INDEX idx_email_sends_to_ts ON email_sends(to_email, sent_at_ms);
CREATE INDEX idx_interruptores_vigentes ON interruptores(expires_at_ms, tenant_id);
CREATE INDEX idx_pair_requests_expires ON pair_requests (expires_at_ms);
CREATE INDEX idx_pair_requests_status ON pair_requests (status);
CREATE INDEX idx_pair_requests_tenant ON pair_requests (tenant_id);
CREATE INDEX idx_tenants_status ON tenants(status);
CREATE INDEX idx_webhooks_event_name ON webhook_events(event_name);
CREATE INDEX idx_webhooks_processed ON webhook_events(processed_ok, received_at_ms);
CREATE INDEX idx_webhooks_resource ON webhook_events(resource_type, resource_id);
CREATE INDEX idx_ws_tickets_expires ON Ws_Tickets (expires_at_ms);
CREATE INDEX ix_license_otp_eventos ON license_otp_eventos (license_id, tipo, at_ms);
CREATE INDEX ix_license_payments_intent ON license_payments (stripe_payment_intent_id);
CREATE INDEX ix_license_payments_license ON license_payments (license_id);
CREATE INDEX ix_licenses_email ON licenses (customer_email);
CREATE INDEX ix_licenses_stripe_customer ON licenses (stripe_customer_id);
CREATE INDEX ix_licenses_stripe_session ON licenses (stripe_checkout_session_id) WHERE stripe_checkout_session_id IS NOT NULL;
CREATE INDEX ix_licenses_tenant ON licenses (tenant_id);
CREATE UNIQUE INDEX ux_license_payments_session_unidad ON license_payments (stripe_checkout_session_id, unidad) WHERE stripe_checkout_session_id IS NOT NULL;
CREATE UNIQUE INDEX ux_reserva_web_claves_activa ON reserva_web_claves(tenant_id) WHERE revoked_at_ms IS NULL;
CREATE TABLE Ws_Tickets ( ticket TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, device_id TEXT NOT NULL, expires_at_ms INTEGER NOT NULL );
CREATE TABLE admin_audit ( audit_id TEXT PRIMARY KEY, action TEXT NOT NULL, license_id TEXT, detail TEXT, at_ms INTEGER NOT NULL );
CREATE TABLE app_releases ( version TEXT NOT NULL, target TEXT NOT NULL DEFAULT 'windows', arch TEXT NOT NULL DEFAULT 'x86_64', channel TEXT NOT NULL DEFAULT 'stable', notes TEXT, pub_date TEXT NOT NULL, signature TEXT NOT NULL, url TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, created_at_ms INTEGER NOT NULL DEFAULT (unixepoch()*1000), PRIMARY KEY (version, target, arch, channel) );
CREATE TABLE canario_cifrado ( id INTEGER PRIMARY KEY CHECK (id = 1), valor TEXT NOT NULL, creado_ms INTEGER NOT NULL );
CREATE TABLE device_challenges ( device_id TEXT NOT NULL, nonce_b64 TEXT NOT NULL, expires_at_ms INTEGER NOT NULL, created_at_ms INTEGER NOT NULL, used_at_ms INTEGER, PRIMARY KEY (device_id, nonce_b64) );
CREATE TABLE devices ( device_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('tpv','handy')), first_seen_at_ms INTEGER NOT NULL DEFAULT (unixepoch()*1000), last_seen_at_ms INTEGER NOT NULL DEFAULT (unixepoch()*1000), revoked_at_ms INTEGER, device_pubkey_b64 TEXT, pubkey_alg TEXT, FOREIGN KEY (tenant_id) REFERENCES tenants(tenant_id) ON DELETE CASCADE );
CREATE TABLE email_codes ( tenant_id TEXT NOT NULL, device_id TEXT NOT NULL, purpose TEXT NOT NULL, subject TEXT NOT NULL, code_hash TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, expires_at_ms INTEGER NOT NULL, consumed_at_ms INTEGER, created_at_ms INTEGER NOT NULL, sends_in_window INTEGER NOT NULL DEFAULT 1, window_started_ms INTEGER NOT NULL, PRIMARY KEY (tenant_id, device_id, purpose) );
CREATE TABLE email_sends ( id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, device_id TEXT NOT NULL, to_email TEXT NOT NULL, proveedor TEXT, ok INTEGER NOT NULL, error_code TEXT, sent_at_ms INTEGER NOT NULL, tipo TEXT NOT NULL DEFAULT 'pedido' );
CREATE TABLE interruptores ( interruptor_id TEXT PRIMARY KEY, interruptor TEXT NOT NULL, tenant_id TEXT NOT NULL DEFAULT '*', version_desde TEXT, version_hasta TEXT, motivo TEXT NOT NULL, expires_at_ms INTEGER NOT NULL, created_at_ms INTEGER NOT NULL DEFAULT (unixepoch()*1000) );
CREATE TABLE license_device_otp ( license_id TEXT NOT NULL, new_device_id TEXT NOT NULL, code_hash TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, expires_at_ms INTEGER NOT NULL, consumed_at_ms INTEGER, created_at_ms INTEGER NOT NULL, PRIMARY KEY (license_id, new_device_id) );
CREATE TABLE license_device_swaps ( swap_id TEXT PRIMARY KEY, license_id TEXT NOT NULL, from_device_id TEXT, to_device_id TEXT NOT NULL, at_ms INTEGER NOT NULL );
CREATE TABLE license_notices ( license_id TEXT NOT NULL, kind TEXT NOT NULL, expires_at_ms INTEGER NOT NULL, sent_at_ms INTEGER NOT NULL, PRIMARY KEY (license_id, kind, expires_at_ms) );
CREATE TABLE license_otp_eventos ( license_id TEXT NOT NULL, tipo TEXT NOT NULL CHECK (tipo IN ('envio','fallo')), at_ms INTEGER NOT NULL );
CREATE TABLE license_payments ( payment_id TEXT PRIMARY KEY, license_id TEXT NOT NULL, kind TEXT NOT NULL, term_months INTEGER NOT NULL, stripe_checkout_session_id TEXT, stripe_payment_intent_id TEXT, reversed_at_ms INTEGER, reversed_reason TEXT, reversed_event_uid TEXT, at_ms INTEGER NOT NULL , unidad INTEGER NOT NULL DEFAULT 1);
CREATE TABLE licenses ( license_id TEXT PRIMARY KEY, license_key_hash TEXT NOT NULL UNIQUE, license_key_enc TEXT, key_short TEXT, tenant_id TEXT, main_device_id TEXT, status TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0, plan TEXT NOT NULL DEFAULT 'standard', term_months INTEGER NOT NULL, origin TEXT NOT NULL, issued_at_ms INTEGER NOT NULL, activated_at_ms INTEGER, expires_at_ms INTEGER, customer_email TEXT NOT NULL, customer_name TEXT, redeemed_into_license_id TEXT, stripe_customer_id TEXT, stripe_checkout_session_id TEXT, stripe_payment_intent_id TEXT, stripe_price_id TEXT, created_at_ms INTEGER NOT NULL, updated_at_ms INTEGER NOT NULL , customer_business_name TEXT, customer_phone TEXT, customer_address_json TEXT, key_email_sent_at_ms INTEGER);
CREATE TABLE pair_claim_fallos ( ip TEXT PRIMARY KEY, fallos INTEGER NOT NULL, ultimo_fallo_ms INTEGER NOT NULL, bloqueado_hasta_ms INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE pair_requests ( pair_code TEXT PRIMARY KEY, secret_hash TEXT NOT NULL, tenant_id TEXT NOT NULL, created_by_device_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','used','expired')), created_at_ms INTEGER NOT NULL, expires_at_ms INTEGER NOT NULL, claimed_at_ms INTEGER, approved_at_ms INTEGER, used_at_ms INTEGER, claimed_by_device_id TEXT, claimed_device_pubkey_b64 TEXT, claimed_device_name TEXT, attempts INTEGER NOT NULL DEFAULT 0, last_attempt_at_ms INTEGER );
CREATE TABLE reserva_web_claves ( clave TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, created_at_ms INTEGER NOT NULL, revoked_at_ms INTEGER, FOREIGN KEY (tenant_id) REFERENCES tenants(tenant_id) ON DELETE CASCADE );
CREATE TABLE reserva_web_dominios ( tenant_id TEXT NOT NULL, origen TEXT NOT NULL, created_at_ms INTEGER NOT NULL, PRIMARY KEY (tenant_id, origen), FOREIGN KEY (tenant_id) REFERENCES tenants(tenant_id) ON DELETE CASCADE );
CREATE TABLE tenant_recovery_emails ( tenant_id TEXT PRIMARY KEY, email TEXT NOT NULL, verified_at_ms INTEGER NOT NULL );
CREATE TABLE tenants ( tenant_id TEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','deleted')), legal_name TEXT, display_name TEXT, email TEXT, phone TEXT, country TEXT, timezone TEXT, notes TEXT, created_at_ms INTEGER NOT NULL DEFAULT (unixepoch()*1000), updated_at_ms INTEGER NOT NULL DEFAULT (unixepoch()*1000) , field_dek TEXT , piloto INTEGER NOT NULL DEFAULT 0 CHECK (piloto IN (0, 1)));
CREATE TABLE webhook_events ( event_uid TEXT PRIMARY KEY, event_name TEXT NOT NULL, resource_type TEXT, resource_id TEXT, sig_hex TEXT, body_sha256 TEXT, payload_json TEXT NOT NULL, received_at_ms INTEGER NOT NULL DEFAULT (unixepoch()*1000), processed_at_ms INTEGER, processed_ok INTEGER NOT NULL DEFAULT 0 CHECK (processed_ok IN (0,1)), error_text TEXT );
